from author import C,S,R,P,T
c=C('不定积分与积分方法')
S(c,'原函数与不定积分：求导验答案',[R('原函数',r"F'(x)=f(x)"),R('不定积分',r"\int f(x)\,dx=F(x)+C"),R('例题',r"\int2x\,dx=x^2+C"),R('验证',r"(x^2+C)'=2x")],[P('原函数在做题里只需先记一句：如果F求导等于f，那么F就是f的一个原函数。不定积分要求写出一族原函数，因此结果一般要加任意常数C。比如二x积分为x平方加C，因为对它求导会回到二x。积分不是把原式再求一次导，而是反过来找能求导得到它的表达式。',[1,2,3],['不定积分答案通常加C','原函数的导数等于被积函数']),P('检验不定积分最可靠的方法，是把答案再求导。求导后若少了一个常数倍或内部导数，说明积分答案还要修正系数。这里的原函数关系是在相应区间内成立，跨过函数没有定义的位置不能不加区分地视为同一个区间。计算时先把基本公式对应起来，再检查结果的导数。',[4],['求导验算可找出系数错误','原函数关系在相应区间内讨论'])],['原函数的定义','不定积分的定义'])
S(c,'基本积分：幂、对数与指数',[R('幂函数',r"\int x^a\,dx=\frac{x^{a+1}}{a+1}+C\quad(a\ne-1)"),R('负一次幂单独记',r"\int\frac{dx}{x}=\ln|x|+C\quad(x\ne0)"),R('指数',r"\int e^x\,dx=e^x+C"),R('一般指数底数',r"\int a^x\,dx=\frac{a^x}{\ln a}+C\quad(a>0,a\ne1)")],[P('幂函数积分的步骤是指数加一，再除以新的指数，最后加C，但原指数等于负一时不能用这一条。负一次幂也就是一除以x，要单独记成自然对数绝对值x。绝对值很重要，因为负数x所在的区间也可能在定义域内，不能随意把它删掉。',[1,2],['指数加一以后还要除以新指数','一除以x属于单独公式']),P('e的x次方积分保持原样，加C；一般底数a的x次方，还要除以自然对数a，底数要求正且不等于一。所有公式都在原式有定义的实数区间内使用。和差可以分开积分，固定常数倍可以提出来。遇到数字系数先提常数，再套表，通常比把整个式子硬塞进一条公式更清楚。',[3,4],['一般底数指数积分除以ln a','线性拆项后逐项积分'])],['基本积分公式'])
S(c,'基本积分：三角与反三角',[R('正弦与余弦',r"\int\sin x\,dx=-\cos x+C,\quad\int\cos x\,dx=\sin x+C"),R('平方型',r"\int\frac{dx}{\cos^2x}=\tan x+C,\quad\int\frac{dx}{\sin^2x}=-\cot x+C"),R('反正切',r"\int\frac{dx}{1+x^2}=\arctan x+C"),R('反正弦',r"\int\frac{dx}{\sqrt{1-x^2}}=\arcsin x+C\quad(|x|<1)")],[P('三角积分里，正弦积分为负余弦，余弦积分为正弦，求导和积分的负号位置不要混。余弦平方在分母对应正切，正弦平方在分母对应负余切，使用时也要避开原分母为零的位置。把每一条结果再求导检查一次，尤其适合纠正负号错误。',[1,2],['正弦积分为负余弦','分母为零的位置不在使用区间']),P('一加x平方在分母，积分对应反正切；根号一减x平方在分母，对应反正弦。两个公式的加减号和根号要分清。若出现a平方加x平方，a为正时，答案是一除以a乘反正切x除以a，再加C；可以令x等于a乘新变量核对，不要把a直接当成一抹掉。',[3,4],['一加平方对应反正切','根号一减平方对应反正弦'])],['基本积分公式'])
S(c,'第一换元法：找到内层的微分',[R('例题',r"\int2x\cos(x^2)\,dx"),R('换元',r"u=x^2,\quad du=2x\,dx"),R('替换积分',r"\int\cos u\,du=\sin u+C"),R('换回原变量',r"\sin(x^2)+C")],[P('第一换元法常见特征是，函数里面有一块表达式，外面恰好带着它的导数。例题余弦里面是x平方，外面有二x，正好可以令u等于x平方，du就是二x乘dx。换元以后，整个二x乘dx一起变成du，不能只换括号里的字母，却把原来的微分因子留在外面。',[1,2],['内层表达式与外部导数要配套','微分必须一起换']),P('积分变成余弦u的积分，得到正弦u加C，再换回x平方，答案正弦x平方加C。若原式只有余弦x平方乘dx，没有二x，就不能直接套成同一个答案。遇到只差常数倍的情况，可以在积分外补偿这个常数倍；缺少一个随x变化的因子，就不是随手除一个数能够补齐的。',[3,4],['不定积分最终换回原变量','缺变因子不能当成缺常数'])],['第一、第二换元积分法'])
S(c,'凑微分：先把系数补齐',[R('例题',r"\int\frac{dx}{3x+2}"),R('换元与微分',r"u=3x+2,\quad du=3dx,\quad dx=\frac13du"),R('结果',r"\frac13\ln|3x+2|+C"),R('同类模板',r"\int e^{2x}\,dx=\frac12e^{2x}+C")],[P('最基础的凑微分题，常常只是差一个常数。对一除以三x加二积分，令u等于三x加二，就有du等于三dx，因此dx是du的三分之一。积分外要保留这个三分之一，而不是因为只看见倒数就直接写自然对数三x加二。',[1,2],['du等于三dx，所以要乘三分之一','系数补偿写在积分外']),P('答案是三分之一乘自然对数绝对值三x加二，再加C。求导验算时，外面的三分之一与内部导数三正好抵消。同样，e的二x次方积分需要乘二分之一。遇到线性内层，优先检查是不是应该除以内层的一次系数，很多基础积分的丢分都发生在这一个系数上。',[3,4],['用求导检验内部系数','别忘绝对值和任意常数'])],['第一、第二换元积分法','基本积分公式'])
S(c,'第二换元法：根式选三角代换',[R('常见选择，a大于零',r"\sqrt{a^2-x^2}:x=a\sin t;\quad\sqrt{a^2+x^2}:x=a\tan t"),R('另一类根式',r"\sqrt{x^2-a^2}:x=a\sec t"),R('例题',r"\int\sqrt{1-x^2}\,dx,\quad x=\sin t,\quad dx=\cos t\,dt"),R('化简',r"\int\cos^2t\,dt=\frac{t}{2}+\frac{\sin2t}{4}+C"),R('换回',r"\frac12\left(\arcsin x+x\sqrt{1-x^2}\right)+C")],[P('第二换元法是主动把x写成新变量的函数。常见根式可以先按表选择：a平方减x平方试正弦，a平方加x平方试正切，x平方减a平方试正割。a取正数，代换区间要使根式和三角函数符号一致，不能把根号下的平方一律直接去掉而忽略绝对值。',[1,2],['先按根式类型选代换','代换区间用于保证符号正确']),P('例题根号一减x平方，令x等于正弦t，选t在负二分之π到二分之π内部，余弦为正。根式变成余弦，dx又贡献一个余弦，所以积分是余弦平方。用降幂公式积分后，把t换成反正弦x，把正弦二t换回二x乘根号一减x平方，得到最后一行。',[3,4,5],['dx也带一个余弦因子','最后把所有新变量换回'])],['第一、第二换元积分法'])
S(c,'分部积分：选u，再选dv',[R('公式',r"\int u\,dv=uv-\int v\,du"),R('例题',r"\int xe^x\,dx"),R('选取',r"u=x,\quad dv=e^x dx,\quad du=dx,\quad v=e^x"),R('代入',r"xe^x-\int e^x dx=(x-1)e^x+C"),R('另一个常见结果',r"\int\ln x\,dx=x\ln x-x+C\quad(x>0)")],[P('分部积分适合两个因子相乘，而且让其中一个求导会更简单的情形。经验上，对数、反三角、多项式常可优先考虑作u，另一部分连同dx作dv，但这只是选取经验，还要看后续是否真的变简单。公式中uv后面是减去积分，这个减号不要靠记忆模糊带过。',[1,2],['选u要让求导更简单','公式中是减去后面的积分']),P('例题x乘指数，让x作u，指数连dx作dv，于是du为dx，v仍为指数，代入得到x乘指数减指数，加C。对ln x积分时，可以把它看成ln x乘一，选u为ln x、dv为dx，得到xln x减x。写清u、dv、du、v四项，再代公式，会比直接展开少出错。',[3,4,5],['四项写齐后再代入','不定积分最后加C'])],['分部积分'])
S(c,'不定积分练习',[R('计算',r"\int x\cos(x^2)\,dx")],[P('暂停练习：x乘余弦x平方，对x积分。它与前面的换元例题只差一个系数。请先令u等于x平方，写出du，再确定原式中的x乘dx对应du的多少倍。不要因为看见同样的余弦括号，就直接把前一道题答案完整抄过来。',[1],['先写du，确定缺少的常数倍','答案在下一页'])],['第一、第二换元积分法'],kind='question')
S(c,'不定积分练习答案',[R('微分关系',r"u=x^2,\quad xdx=\frac12du"),R('积分与换回',r"\frac12\int\cos u\,du=\frac12\sin(x^2)+C")],[P('du等于二x乘dx，所以x乘dx是二分之一du。原积分得到二分之一正弦x平方，再加C。验算时二分之一乘内部导数二x，正好还原成原来的x乘余弦x平方。这类看起来只差一个数字的题，最适合用求导检查，不需要再换一种复杂方法重算。',[1,2],['答案有二分之一','求导后恰好恢复原题'])],['第一、第二换元积分法'],kind='answer')

c=C('定积分与反常积分')
S(c,'微积分基本定理：上限减下限',[R('条件与公式',r"f\in C[a,b],\quad F'=f,\quad\int_a^b f(x)\,dx=F(b)-F(a)"),R('例题',r"\int_1^2 2x\,dx"),R('原函数',r"F(x)=x^2"),R('代入',r"F(2)-F(1)=4-1=3")],[P('普通定积分的基本计算，先找原函数，再用上限代入减下限代入。被积函数在闭区间连续时，可以直接使用这一套基本公式。例题二x从一积到二，原函数是x平方，所以上限得到四，下限得到一，作差是三。别把两个端点直接代进被积函数，那还没有完成积分。',[1,2,3],['先求原函数，再代端点','顺序是上限减下限']),P('定积分的结果是一个数，不需要在最后加C，原函数中的常数在相减时会抵消。使用公式前先检查积分区间里有没有分母为零、对数或根式不合法等问题。若内部存在奇点，就可能是反常积分，要分开取极限，不能只看端点代入有限就宣布普通定积分算完。',[4],['定积分最后不加C','区间内部的奇点也要检查'])],['微积分基本定理'])
S(c,'积分变限函数：把上限放进去',[R('连续条件下',r"G(x)=\int_a^x f(t)\,dt\quad\Longrightarrow\quad G'(x)=f(x)"),R('复合上限',r"G(x)=\int_a^{u(x)}f(t)\,dt\quad\Longrightarrow\quad G'(x)=f(u(x))u'(x)"),R('例题',r"G(x)=\int_0^{x^2}\sin(t^2)\,dt"),R('结果',r"G'(x)=2x\sin(x^4)")],[P('变上限积分求导，看到上限是x，就把被积函数里的积分变量换成x。若上限是一整块u括号x，就先把这一整块放进去，再乘上限的导数。这里仍然是链式法则，不需要先把积分真的算出来。有些被积函数找不到简单的原函数，也不妨碍直接求这个变限函数的导数。',[1,2],['先代入上限，再乘上限导数','不需要先求出积分的具体表达式']),P('例题内部是正弦t平方，上限是x平方。把t换成x平方后，t平方会变成x的四次方，再乘上限x平方的导数二x，得到二x乘正弦x四次方。最常见两个错误是只把t替成x，或者虽然替对了却漏掉外面的二x。先替换整块，再乘导数，分两行写更稳。',[3,4],['t平方要变成x的四次方','外面还要乘二x'])],['积分变限函数求导'])
S(c,'上下限都变：上减下',[R('模板',r"G(x)=\int_{u(x)}^{v(x)}f(t)\,dt"),R('求导',r"G'(x)=f(v(x))v'(x)-f(u(x))u'(x)"),R('例题',r"G(x)=\int_x^{x^2}\sin(t^2)\,dt"),R('结果',r"G'(x)=2x\sin(x^4)-\sin(x^2)")],[P('上下限都含x时，分别处理上限和下限，再相减。上限放进被积函数，乘上限导数；减去下限放进去，再乘下限导数。符号顺序固定是上减下。下限那一整项要带减号，若下限本身又有负的导数，最后还要把这两个负号正确整理。',[1,2],['上限贡献减去下限贡献','上下限各自都要乘导数']),P('例题上限仍产生二x乘正弦x四次方，下限是x，贡献正弦x平方乘一，减去它即可。这个简单模板要求被积函数只是积分变量t的函数。若积分内部还另外含x，例如x乘t，先把x当作参数提出来并化简，然后对整个结果求导，不能机械只替换两个端点。',[3,4],['下限项也必须写出来','积分内部另含x时先化简再求导'])],['积分变限函数求导'])
S(c,'定积分性质：换序、分段与估值',[R('交换上下限',r"\int_b^a f(x)\,dx=-\int_a^b f(x)\,dx"),R('区间相加',r"\int_a^b f+\int_b^c f=\int_a^c f"),R('常数倍与和差',r"\int_a^b(\alpha f+\beta g)=\alpha\int_a^b f+\beta\int_a^b g"),R('估值，a小于b',r"m\le f\le M\quad\Longrightarrow\quad m(b-a)\le\int_a^b f\le M(b-a)")],[P('定积分的性质题，先注意交换上下限会变号；同一点到同一点积分为零；相邻区间可以拼起来，必要时也可以拆开。固定常数倍和和差可以分开处理。题目给了几个区间的积分数值时，通常不需要猜原函数，只要把要求的区间按方向和分段关系整理出来。',[1,2,3],['上下限反向要变号','区间可以按方向拆开拼接']),P('估值题在a小于b时，把函数的下界和上界分别乘区间长度，就得到积分的下界和上界。例如函数始终在二与三之间，区间长度四，则积分在八与十二之间。先确认这是通常可积的情形，并且长度使用b减a；若原题上下限反向，先换方向处理符号。',[4],['估值先确认区间方向','函数上下界乘区间长度'])],['定积分的性质'])
S(c,'偶倍奇零：必须是对称区间',[R('偶函数',r"f(-x)=f(x):\quad\int_{-a}^a f(x)dx=2\int_0^a f(x)dx"),R('奇函数',r"f(-x)=-f(x):\quad\int_{-a}^a f(x)dx=0"),R('例题',r"\int_{-1}^1(x^3+x^2+1)\,dx"),R('分开处理',r"2\int_0^1(x^2+1)dx=\frac83")],[P('偶倍奇零先检查两个条件：积分区间以零为中心对称，积分本身按题目通常意义存在。偶函数保留零到a的一半积分再乘二，奇函数直接为零。若被积式是几项相加，可以把奇的部分和偶的部分分开，不必因为整个式子既不奇也不偶就放弃这项技巧。',[1,2],['区间必须关于零对称','先确认积分存在']),P('例题x立方是奇项，积分为零；x平方与常数一是偶项，算零到一再乘二，得到三分之八。用原函数核对，先算三分之一加一得到三分之四，再乘二得到三分之八。后面会看到一除以x的反常积分，虽然形式是奇函数，也不能因此在穿过零的区间上直接写零。',[3,4],['只把奇项消去，偶项仍需积分','先算三分之一加一，再乘二，结果三分之八'])],['定积分偶倍奇零'])
S(c,'定积分换元：上下限一起换',[R('例题',r"\int_0^1 2x e^{x^2}\,dx"),R('变量与端点',r"u=x^2,\ du=2xdx,\quad x=0\Rightarrow u=0,\ x=1\Rightarrow u=1"),R('新变量积分',r"\int_0^1 e^u\,du=e-1"),R('两种一致路线',r"\int_0^1 2xe^{x^2}dx=\left[e^{x^2}\right]_0^1")],[P('定积分也可以换元，但变量、微分和上下限必须配套一起换。例题令u等于x平方，二x乘dx变成du，原来的x为零和一，分别换成u为零和一。虽然这次数字碰巧没变，也要写清它们现在表示新变量的取值，不能把“看起来一样”当作不用换上下限。',[1,2],['换变量、微分、上下限三项配套','本题端点数字碰巧相同']),P('换好以后直接对u积分，得到e减一，不需要再把u换回x。另一条路线是先当不定积分做，求得e的x平方次方，再代原来的x上下限。两条路线都可以，但不能用新变量的原函数去代旧变量的端点。写清自己选哪条路线，就不会在最后一步混用字母与数字。',[3,4],['新变量配新上下限','换回x时才使用原x上下限'])],['第一、第二换元积分法'])
S(c,'反常积分：先找奇点再分开',[R('无限区间',r"\int_1^\infty f(x)dx=\lim_{b\to\infty}\int_1^b f(x)dx"),R('无界端点',r"\int_0^1 f(x)dx=\lim_{\varepsilon\to0^+}\int_\varepsilon^1 f(x)dx"),R('内部奇点必须分两边',r"\int_{-1}^1\frac{dx}{x}=\int_{-1}^0\frac{dx}{x}+\int_0^1\frac{dx}{x}"),R('右侧已经发散',r"\lim_{\varepsilon\to0^+}[-\ln\varepsilon]=+\infty")],[P('反常积分有两类明显特征：区间伸到无穷，或者被积函数在端点及内部某处无界。先用有限端点或避开奇点的小距离写成普通积分，再取单侧极限。只有需要的各个极限都有限，才能说收敛。若区间内有奇点，必须在那个点两侧分别计算，不能让两个发散部分互相抵消。',[1,2],['无穷端点或无界函数先改成极限','内部奇点要拆成两侧']),P('比如负一到一的一除以x，在零处要分两边。右侧从正ε积到一，得到负ln ε，趋于正无穷，已经足以判定普通反常积分发散。若只用对称截断让两边抵消，算的是另一种主值，不是本课普通反常积分的收敛。因此奇函数这个外形不能替代存在性检查。',[3,4],['一除以x跨过零时发散','主值抵消不等于通常收敛'])],['反常积分敛散性','定积分偶倍奇零'])
S(c,'反常积分：两张幂次判别表',[R('无穷端点：p大于1才收敛','\\int_1^\\infty\\frac{dx}{x^p},\\quad p>1'),R('零端点：p小于1才收敛','\\int_0^1\\frac{dx}{x^p},\\quad p<1'),R('常见例子',r"\int_1^\infty\frac{dx}{x^2}=1,\quad\int_0^1\frac{dx}{\sqrt{x}}=2"),R('比较的例子',r"\frac1{1+x^2}\sim\frac1{x^2}\quad(x\to\infty)")],[P('这两张表必须分开记：一到正无穷的一除以x的p次方，p大于一才收敛；零到一同样的形式，p小于一才收敛。p等于一，两种都发散。看清困难发生在无穷端还是零端，再判断不等号方向。不要只背“p大于一收敛”而把它用到零附近。',[1,2],['无穷端要p大于一','零端要p小于一；等于一都发散']),P('例子里无穷端的平方分母收敛且值为一，零端根号分母对应p为二分之一，收敛且值为二。对非负函数，可以用比较或极限比较；例如无穷远处一除以一加x平方，与一除以x平方的比值趋于一，因此同敛散。比较时要选同一端点附近的模型，并检查非负及正的有限比值等条件。',[3,4],['比较法在相应困难端点附近用','极限比为正的有限常数时同敛散'])],['反常积分敛散性'])
S(c,'定积分练习',[R('函数',r"G(x)=\int_1^{x^3}\cos t\,dt"),R('要求',r"G'(x)=\ ?")],[P('暂停练习：从一到x立方，对余弦t积分得到函数G，求G的导数。下限是一，固定不变。请先把上限这一整块代进余弦，再乘它自己的导数。题目问的是函数的导数，不是某个固定上下限积分值，不能一开始就把x当成常数丢掉。',[1,2],['上限整块代入，并乘上限导数','答案在下一页'])],['积分变限函数求导'],kind='question')
S(c,'定积分练习答案',[R('代入上限',r"\cos(x^3)"),R('乘上限导数',r"G'(x)=3x^2\cos(x^3)")],[P('把上限x立方放进被积函数，先得到余弦x立方，再乘上限的导数三x平方，答案三x平方乘余弦x立方。下限固定为一，对这一步求导没有额外项。若你的结果写成正弦x立方，那是在处理积分表达式，还没有按题目要求完成最终的求导。',[1,2],['结果三x平方乘余弦x立方','固定下限不另产生导数项'])],['积分变限函数求导'],kind='answer')
